const rows = $input.all().map(i => i.json).filter(r => r.sender && r.kind);
const body = $('Webhook').first().json.body || {};
const since = new Date(body.since);
if (isNaN(since.getTime())) { throw new Error('Invalid since value.'); }
const valid = rows.filter(r => /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+$/.test(String(r.sender).trim()));
if (valid.length === 0) {
  return [{ json: { skip: true, found: 0, new: 0, message: 'No enabled allowed senders.' } }];
}
const kinds = {};
for (const r of valid) {
  const address = String(r.sender).trim().toLowerCase();
  if (!kinds[address]) { kinds[address] = r.kind; }
}
const addresses = Object.keys(kinds);
const epoch = Math.floor(since.getTime() / 1000);
const query = '(' + addresses.map(a => 'from:' + a).join(' OR ') + ') after:' + epoch;
return [{ json: { skip: false, query, kinds } }];

const kinds = $('Build Gmail query').first().json.kinds;
const rows = [];
function header(m, name) {
  const headers = (m.payload && m.payload.headers) || [];
  const hit = headers.find(h => String(h.name).toLowerCase() === name);
  return hit ? hit.value : null;
}
function fromOf(m) {
  if (typeof m.from === 'string') { return m.from; }
  if (m.from && m.from.text) { return m.from.text; }
  return header(m, 'from') || '';
}
function htmlOf(m) {
  if (typeof m.html === 'string') { return m.html; }
  const walk = (part) => {
    if (!part) { return null; }
    if (part.mimeType === 'text/html' && part.body && part.body.data) {
      return Buffer.from(part.body.data, 'base64').toString('utf8');
    }
    for (const child of part.parts || []) {
      const found = walk(child);
      if (found) { return found; }
    }
    return null;
  };
  return walk(m.payload);
}
for (const item of $input.all()) {
  const m = item.json;
  if (!m || !m.id) { continue; }
  const from = fromOf(m);
  const match = from.match(/<([^>]+)>/);
  const address = (match ? match[1] : from).trim().toLowerCase();
  const kind = kinds[address];
  if (!kind) { continue; }
  const received = m.internalDate ? new Date(Number(m.internalDate)) : new Date(m.date);
  if (isNaN(received.getTime())) { throw new Error('Message has no usable date.'); }
  rows.push({
    gmail_message_id: String(m.id),
    kind: kind,
    sender: from,
    subject: m.subject || header(m, 'subject') || null,
    snippet: String(m.snippet || '').slice(0, 200) || null,
    body_html: kind === 'job_alert' ? (htmlOf(m) || null) : null,
    received_at: received.toISOString()
  });
}
return [{ json: { rows } }];

const found = $('Get Gmail messages').all().filter(i => i.json && i.json.id).length;
const inserted = $input.all().filter(i => i.json && i.json['?column?'] === 1).length;
let message = 'Gmail returned ' + found + ' messages; ' + inserted + ' new emails saved.';
if (found >= 100) { message += ' Limit of 100 reached; older messages may remain.'; }
return [{ json: { found: found, new: inserted, message: message } }];
